<script>
(()=>{const form=document.querySelector('[data-web-editor]');if(!form)return;
form.querySelectorAll('[data-card-list]').forEach(list=>{list.dataset.next=String(Math.max(-1,...Array.from(list.children,c=>Number(c.dataset.index)))+1);});
form.addEventListener('change',e=>{if(!e.target.matches('[data-registered-professional]'))return;const option=e.target.selectedOptions[0];if(!option||!Number(option.value))return;const card=e.target.closest('[data-web-card]');['name','role','registration'].forEach(key=>{const field=card.querySelector('[name$="['+key+']"]');if(field)field.value=option.dataset[key]||'';});});
form.addEventListener('click',e=>{const add=e.target.closest('[data-add-card]');if(add){const kind=add.dataset.addCard,list=form.querySelector('[data-card-list="'+kind+'"]');if(list.children.length>=Number(list.dataset.limit)){alert('Limite de cartões atingido.');return;}const next=Number(list.dataset.next||list.children.length);list.dataset.next=String(next+1);const template=document.getElementById('template-'+kind);const holder=document.createElement('div');holder.innerHTML=template.innerHTML.replaceAll('__INDEX__',String(next));list.append(holder.firstElementChild);return;}const remove=e.target.closest('[data-remove-card]');if(remove){remove.closest('[data-web-card]').remove();return;}const move=e.target.closest('[data-move]');if(move){const card=move.closest('[data-web-card]');if(move.dataset.move==='up'&&card.previousElementSibling)card.previousElementSibling.before(card);if(move.dataset.move==='down'&&card.nextElementSibling)card.nextElementSibling.after(card);}});
})();
</script>
